import sys

def count_ways(P, T):
    MOD = 10**9 + 7
    n, m = len(P), len(T)
    positions = []

    for i in range(m - n + 1):
        if T[i:i+n] == P:
            positions.append(i + 1)

    def is_good_number(x):
        for d in range(1, 10):
            if x % d != 0:
                return False
        return True

    dp = [0] * (len(positions) + 1)
    dp[0] = 1

    for i in range(1, len(positions) + 1):
        dp[i] = dp[i - 1]
        product = 1
        for j in range(i, 0, -1):
            product *= positions[j - 1]
            if is_good_number(product):
                dp[i] = (dp[i] + dp[j - 1]) % MOD

    return (dp[-1] - 1) % MOD

input = sys.stdin.read().split()
P = input[0]
T = input[1]
print(count_ways(P, T))
